import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class Solution {
    private int count = 0;
    private int[] result = new int[6];
    public void next(int price) {
        if (count == 0) {
            result[count++] = price * 100;
        } else if (price <= result[count - 1]) {
            for (int i = count; i < result.length; i++) {
                result[i] = result[i - 1];
            }
            result[0] = price * 100;
            ++count;
        }
    }

    public int[] solution(int[] prices) {
        while (prices.length > 0) {
            next(prices[0]);
            --prices[0];
        }
        return result;
    }
}

public class SolutionTest {

    @Test
    public void test_solution() {
        Solution sol = new Solution();
        int[] prices = {new Integer[]{1}, new Integer[]{2}, new Integer[]{3}};
        for (int i : sol.solution(prices)) {
            System.out.print(i + " ");
        }
    }

    @Test
    public void test_count() {
        Solution sol = new Solution();
        int count = 0;
        sol.count = count;
        assertEquals(1, sol.next(new Integer[]{10000}));
        assertEquals(2, sol.next(new Integer[]{80000}));
    }

    @Test
    public void test_result() {
        Solution sol = new Solution();
        for (int i = 0; i < sol.result.length; i++) {
            System.out.print(sol.result[i] + " ");
        }
    }

}
